using System.ComponentModel;
using Microsoft.Agents.AI;
using Microsoft.Extensions.AI;

var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable before running.");

var modelId = Environment.GetEnvironmentVariable("OPENAI_MODEL") ?? "gpt-4o-mini-2024-07-18";

IChatClient chatClient = new OpenAI.OpenAIClient(apiKey)
    .GetChatClient(modelId)
    .AsIChatClient();

// ── Tool state ──────────────────────────────────────────────────────────────
var notebook = new Notebook();

// ── Define tools ────────────────────────────────────────────────────────────
var tools = new AIFunction[]
{
    AIFunctionFactory.Create(
        (
            [Description("The search query to look up on the web")]
            string query
        ) =>
        {
            Console.ForegroundColor = ConsoleColor.DarkYellow;
            Console.WriteLine($"  🔍 Searching: \"{query}\"");
            Console.ResetColor();

            // Simulated search results — swap with a real search API in production.
            return
                $"Search results for \"{query}\":\n" +
                $"1. \"{query}\" - Wikipedia overview covering history, key concepts, and notable developments. " +
                $"The topic has seen significant advances in recent years with growing interest from researchers and industry.\n" +
                $"2. \"Latest advances in {query}\" - Recent breakthroughs include improved methodologies, " +
                $"new frameworks, and broader adoption across multiple domains.\n" +
                $"3. \"Challenges and future of {query}\" - Experts identify scalability, reliability, " +
                $"and ethical considerations as key challenges, with promising solutions on the horizon.\n" +
                $"4. \"{query} practical applications\" - Real-world deployments span healthcare, finance, " +
                $"education, and engineering, demonstrating measurable impact.\n" +
                $"5. \"{query} getting started guide\" - Comprehensive tutorial covering foundational concepts, " +
                $"tools, and best practices for newcomers.";
        },
        name: "WebSearch",
        description: "Search the web for information on a topic. Returns a list of result snippets."),

    AIFunctionFactory.Create(
        (
            [Description("Title or label for the note")]
            string title,
            [Description("Content of the note with key findings")]
            string content
        ) =>
        {
            notebook.Save(title, content);

            Console.ForegroundColor = ConsoleColor.DarkGreen;
            Console.WriteLine($"  📝 Note saved: \"{title}\" ({notebook.Count} total)");
            Console.ResetColor();

            return $"Note \"{title}\" saved. You now have {notebook.Count} note(s).";
        },
        name: "SaveNote",
        description: "Save a research note with a title and content for later summarization."),

    AIFunctionFactory.Create(
        () =>
        {
            Console.ForegroundColor = ConsoleColor.DarkCyan;
            Console.WriteLine($"  📖 Retrieving {notebook.Count} note(s)");
            Console.ResetColor();

            return notebook.GetAll();
        },
        name: "GetNotes",
        description: "Retrieve all saved research notes to review or summarize findings."),
};

// ── Create agent ────────────────────────────────────────────────────────────
var agent = new ChatClientAgent(chatClient, "ResearchAgent")
{
    Instructions =
        """
        You are a research agent. Your job is to research a topic thoroughly and produce a clear summary.

        Follow this workflow:
        1. Use WebSearch to find information about the topic (search 2-3 different angles).
        2. Use SaveNote to record key findings from each search.
        3. Use GetNotes to review everything you've gathered.
        4. Produce a well-structured final summary with sections for Overview, Key Findings, and Conclusion.

        Be thorough but concise. Cite the search results you found.
        """,
    Tools = tools,
};

// ── Get the research topic ──────────────────────────────────────────────────
Console.WriteLine("╔══════════════════════════════════════════╗");
Console.WriteLine("║       🔬 AI Research Agent               ║");
Console.WriteLine("╚══════════════════════════════════════════╝");
Console.WriteLine();

string topic;
if (args.Length > 0)
{
    topic = string.Join(' ', args);
}
else
{
    Console.Write("Enter a research topic: ");
    topic = Console.ReadLine()?.Trim() ?? "artificial intelligence";
}

Console.WriteLine();
Console.WriteLine($"Researching: \"{topic}\"");
Console.WriteLine(new string('─', 50));

// ── Run the agent ───────────────────────────────────────────────────────────
var history = new List<ChatMessage>
{
    new(ChatRole.User, $"Research the following topic and provide a comprehensive summary: {topic}"),
};

var options = new AgentInvokeOptions
{
    MaximumIterations = 15,
    Temperature = 0f,
};

string finalResponse = "";

await foreach (var response in agent.InvokeAsync(history, options))
{
    if (response.Role == ChatRole.Assistant && !string.IsNullOrWhiteSpace(response.Text))
    {
        finalResponse = response.Text;
    }
}

Console.WriteLine();
Console.WriteLine(new string('═', 50));
Console.WriteLine("📋 RESEARCH SUMMARY");
Console.WriteLine(new string('═', 50));
Console.WriteLine(finalResponse);
Console.WriteLine(new string('═', 50));
Console.WriteLine($"Notes collected: {notebook.Count}");

// ── Notebook helper ─────────────────────────────────────────────────────────
sealed class Notebook
{
    private readonly List<(string Title, string Content)> _notes = [];

    public int Count => _notes.Count;

    public void Save(string title, string content) =>
        _notes.Add((title, content));

    public string GetAll()
    {
        if (_notes.Count == 0)
            return "No notes saved yet.";

        return string.Join("\n\n---\n\n",
            _notes.Select((n, i) => $"## Note {i + 1}: {n.Title}\n{n.Content}"));
    }
}

